const tag = pm.variables.get("tag")
const baseUrl = pm.environment.get("BASE");

// Validate a single tag's response
function validateTagResponse(tag, body, statusCode, responseTime) {
  pm.test(`[${tag}] Status code is 200 or 201`, () => {
    pm.expect(statusCode).to.be.oneOf([200, 201]);
  });

  pm.test(`[${tag}] Response time is under 3000ms`, () => {
    pm.expect(responseTime).to.be.below(3000);
  });

  if (statusCode === 200) {
      pm.test(`[${tag}] Response is a non-empty array`, () => {
        pm.expect(body).to.be.an("array").and.have.length.above(0);
      });

      pm.test(`[${tag}] Each game has all required keys`, () => {
        body.forEach((game) => {
          expectedKeys.forEach(key => {
            pm.expect(game, `[${tag}] Game[${game.id}] missing key "${key}"`).to.have.property(key);
          });
        });
      });
  } else {
      pm.test(`[${tag}] Response indicates no data found`, () => {
          pm.expect(body).to.have.property("status", 0);
          pm.expect(body).to.have.property("status_message");
      });
  }
}

// Safely handle the response
try {
    const jsonData = pm.response.json();
    validateTagResponse(tag, jsonData, pm.response.code, pm.response.responseTime);
} catch (e) {
    pm.test("Response is valid JSON", () => {
        pm.expect(false, "Response was not valid JSON: " + e.message).to.be.true;
    });
}

