];

function getRandomTags(list, count = 5) {
    const target = Math.min(count, list.length);   // safety guard
    const indexes = new Set();

    while (indexes.size < target) {
        indexes.add(Math.floor(Math.random() * list.length));
    }

    return [...indexes].map(i => list[i]).join(".");
}

